def yard_becomes_the_first_client(apps, schema_editor):
    """Each practice's link to the C-gate yard becomes its first client.

    The visits and the bills that exist were all made at that yard.
    """
    Link = apps.get_model('cvet', 'PracticeYardLink')
    Client = apps.get_model('cvet', 'Client')
    Visit = apps.get_model('cvet', 'Visit')
    Bill = apps.get_model('cvet', 'Bill')
    Business = apps.get_model('core', 'BusinessSettings')
    business = Business.objects.first()
    name = (business.business_name if business else '') or 'The yard'
    for link in Link.objects.all():
        client = Client.objects.create(practice_id=link.practice_id, name=name, kind='yard', yard_link=link)
        Visit.objects.filter(practice_id=link.practice_id).update(practice_client=client)
        Bill.objects.filter(practice_id=link.practice_id).update(practice_client=client)


